using System.Text;

namespace AlchemyStars.Engine;

public static partial class QcProjectGenerator
{
    // Section names and include layout follow Source-Files-MW-Public/Weapons/Assault Rifles/akilo47.
    private static void WriteOfficialEntries(string output, string modelDirectory, string weaponName, string materials,
        string receiver, IReadOnlyList<string> layers, string transitions)
    {
        File.WriteAllText(Path.Combine(output, "weapon_viewmodel.qc"), $$"""
            // Generated by Alchemy Stars. Compile this file, not its include fragments.
            $illumposition 0 0 0
            $origin 0 0 0 -90

            $modelname "{{modelDirectory}}v_{{weaponName}}.mdl"

            // Meshes
            $include "meshes.qc"

            // C Hands Bones
            $include "bones_chands.qci"

            // MW Rig Bones
            $include "bones_mwrig.qci"

            // Weapon Bones
            $include "bones_weapon.qc"

            // Attachments
            $include "attachments.qc"

            $surfaceprop "weapon"
            $contents "solid"
            $mostlyopaque

            // Materials
            $cdmaterials "{{materials}}"

            // IK
            $ikchain rhand "j_wrist_ri" knee 0.707 0.707 0
            $ikchain lhand "j_wrist_le" knee 0.707 0.707 0

            // Animations
            $include "animations_basic.qc"
            $include "animations_ads.qc"
            $include "animations_delta.qc"
            """);
        var delta = new StringBuilder("// Pose parameters\n\n");
        foreach (var layer in layers.Append("aim_offset").Distinct())
            delta.AppendLine($"$poseparameter \"{layer}\" 0 1 loop 0");
        delta.AppendLine("\n// Reference\n\n$include \"additives/_reference.qc\"");
        delta.AppendLine("\n// Transitions\n").Append(transitions);
        delta.AppendLine("\n// Pose layers\n");
        foreach (var layer in layers) delta.AppendLine($"$include \"additives/{layer}.qc\"");
        File.WriteAllText(Path.Combine(output, "animations_delta.qc"), delta.ToString());

        File.WriteAllText(Path.Combine(output, "weapon_worldmodel.qc"), $$"""
            // Generated by Alchemy Stars. Compile this file, not its include fragments.
            $illumposition 0 0 0

            $modelname "{{modelDirectory}}w_{{weaponName}}.mdl"

            // Meshes
            $include "meshes_worldmodel.qc"

            // Weapon Bones
            $include "bones_weapon_worldmodel.qc"

            // Attachments
            $include "attachments_worldmodel.qc"

            $surfaceprop "weapon"
            $contents "solid"
            $mostlyopaque

            // Materials
            $cdmaterials "{{materials}}"

            // Sequences
            $sequence "idle" {
                "meshes/w_{{receiver}}.smd"
                fps 30
            }

            // Collision
            $collisionmodel "meshes/w_{{receiver}}.smd" {
                $mass 5
            }
            """);
    }

    /// <summary>ARC9 / Both / MW Base single-file entries: one flat include list per model (Flatten may inline it later).</summary>
    private static void WriteCombinedEntries(string viewQc, string worldQc, QcTarget target, string modelDirectory, string weaponName,
        string common, string receiver, IEnumerable<string> poseParameters, IReadOnlyList<string> layers, bool useArc9)
    {
        var view = new StringBuilder($"// Generated by Alchemy Stars from CAST assets (target: {target})\n");
        view.AppendLine($"$modelname \"{modelDirectory}v_{weaponName}.mdl\"");
        view.AppendLine("$origin 0 0 0 -90");
        view.AppendLine("$include \"meshes.qc\"\n$include \"bones.qci\"\n$include \"bones_chands.qci\"\n$include \"attachments.qc\"");
        view.Append(common);
        view.AppendLine("$ikchain rhand \"j_wrist_ri\" knee 0.707 0.707 0");
        view.AppendLine("$ikchain lhand \"j_wrist_le\" knee 0.707 0.707 0");
        // aim param is always declared: hip/ADS sequences blend on it.
        foreach (var param in poseParameters) view.AppendLine($"$poseparameter \"{param}\" 0 1 loop 0");
        view.AppendLine("$include \"animations_basic.qc\"");
        view.AppendLine("$include \"additives/_reference.qc\"");
        foreach (var layer in layers) view.AppendLine($"$include \"additives/{layer}.qc\"");
        if (useArc9) view.AppendLine("$include \"animations_arc9.qc\"");
        File.WriteAllText(viewQc, view.ToString());

        var world = new StringBuilder("// Generated by Alchemy Stars. The weapon root sits on ValveBiped.Bip01_R_Hand;\n// align it with SWEP.WorldModelOffset (ARC9) or by editing the root $definebone.\n");
        world.AppendLine($"$modelname \"{modelDirectory}w_{weaponName}.mdl\"");
        world.AppendLine("$include \"meshes_worldmodel.qc\"\n$include \"bones_worldmodel.qci\"\n$include \"attachments_worldmodel.qc\"");
        world.Append(common);
        world.AppendLine($"$sequence \"idle\" \"meshes/w_{receiver}.smd\" fps 30");
        world.AppendLine($"$collisionmodel \"meshes/w_{receiver}.smd\" {{\n\t$mass 5\n}}");
        File.WriteAllText(worldQc, world.ToString());
    }

    private static void FormatOfficialFiles(string output, IEnumerable<string> entries)
    {
        // Only touch generated files reachable from these compile entries, never unrelated QCs in the output folder.
        var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        void Format(string file)
        {
            if (!visited.Add(file)) return;
            var source = File.ReadAllText(file);
            foreach (var line in source.Split('\n'))
            {
                var include = IncludeLine().Match(line);
                if (include.Success) Format(Path.Combine(output, include.Groups[1].Value.Replace('/', Path.DirectorySeparatorChar)));
            }
            File.WriteAllText(file, FormatOfficialQc(source));
        }
        foreach (var entry in entries) Format(entry);
    }

    /// <summary>What a QC line is, for indentation and spacing. Events are "{ event ... }" one-liners, not blocks.</summary>
    private enum QcLine { Blank, Comment, Open, Close, Event, Source, Include, Timing, Command }

    private static QcLine Classify(string line) => line switch
    {
        "" => QcLine.Blank,
        "}" => QcLine.Close,
        _ when line.StartsWith("{ event ", StringComparison.Ordinal) => QcLine.Event,
        _ when line.StartsWith("//", StringComparison.Ordinal) => QcLine.Comment,
        _ when line.EndsWith('{') => QcLine.Open,
        _ when line.StartsWith('"') => QcLine.Source,
        _ when line.StartsWith("$include", StringComparison.Ordinal) || line.StartsWith("ikrule", StringComparison.Ordinal) => QcLine.Include,
        _ when line.StartsWith("fps ", StringComparison.Ordinal) || line is "snap" or "loop" || line.StartsWith("fade", StringComparison.Ordinal) => QcLine.Timing,
        _ => QcLine.Command,
    };

    /// <summary>
    /// Blank line before: top-level $sequence and section comments; inside a block, where events, includes or timing
    /// start after a different kind of line (akilo47 groups a sequence body as sources / events / macros / timing).
    /// </summary>
    private static bool BlankBefore(QcLine kind, string line, QcLine? previous, int depth) => depth == 0
        ? kind == QcLine.Comment || line.StartsWith("$sequence", StringComparison.Ordinal)
        : previous is { } before && before != kind && kind is QcLine.Event or QcLine.Include or QcLine.Timing;

    /// <summary>Whitespace only: tabs inside blocks, blank lines between sections, at most one blank in a row, CRLF.</summary>
    private static string FormatOfficialQc(string source)
    {
        var lines = new List<string>();
        var depth = 0;
        QcLine? previous = null; // last line kind in the current block; null right after "{"
        bool LastIsBlank() => lines.Count == 0 || lines[^1].Length == 0;
        foreach (var raw in source.ReplaceLineEndings("\n").Split('\n'))
        {
            var line = raw.Trim();
            var kind = Classify(line);
            if (kind == QcLine.Blank)
            {
                if (!LastIsBlank()) lines.Add("");
                continue;
            }
            if (kind == QcLine.Close)
            {
                if (--depth < 0) throw new InvalidDataException("Unexpected closing brace in generated QC.");
                if (lines.Count > 0 && lines[^1].Length == 0) lines.RemoveAt(lines.Count - 1);
            }
            else if (!LastIsBlank() && BlankBefore(kind, line, previous, depth)) lines.Add("");
            lines.Add(new string('\t', depth) + line);
            if (kind == QcLine.Open) depth++;
            previous = kind == QcLine.Open ? null : kind;
        }
        if (depth != 0) throw new InvalidDataException("Unbalanced generated QC block.");
        return string.Join("\r\n", lines).TrimEnd() + "\r\n";
    }
}
